import{_ as r,C as a,o as s,c as n,j as e,a as l,E as i,ag as h}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Seller Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-dashboard.md","filePath":"sellers/seller-dashboard.md","lastUpdated":1787558413000}'),g={name:"sellers/seller-dashboard.md"};function d(c,t,u,p,m,f){const o=a("ImagePopup");return s(),n("div",null,[t[0]||(t[0]=e("h1",{id:"seller-dashboard",tabindex:"-1"},[l("Seller Dashboard "),e("a",{class:"header-anchor",href:"#seller-dashboard","aria-label":'Permalink to "Seller Dashboard"'},"​")],-1)),t[1]||(t[1]=e("p",null,"The Dashboard is the first screen a seller sees after signing in — a single read on how the store is doing right now, what needs attention today, and how complete the seller's own profile is.",-1)),t[2]||(t[2]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"What you'll learn"),e("ul",null,[e("li",null,"What each block of the dashboard shows"),e("li",null,"How the date range changes the figures"),e("li",null,'What the "Things to do" list is telling you')])],-1)),i(o,{src:"/images/seller-dashboard/dashboard.png",alt:"Seller dashboard with profile score, overview cards, things to do, overall details and stock threshold"}),t[3]||(t[3]=h('<h2 id="the-greeting-and-profile-score" tabindex="-1">The greeting and profile score <a class="header-anchor" href="#the-greeting-and-profile-score" aria-label="Permalink to &quot;The greeting and profile score&quot;">​</a></h2><p>The page opens with <strong>Hi! <em>your name</em></strong> and a short prompt to review what&#39;s going on in your store. Beside it sits your <strong>Profile Score</strong> — how complete your seller profile is — with a <strong>Complete Your Profile →</strong> link straight to <a href="/sellers/seller-profile">Manage Profile</a>.</p><p>The score is worth clearing early: an incomplete profile blocks the product create flow, so a low score is usually the reason a seller can&#39;t list anything yet.</p><h2 id="the-date-range" tabindex="-1">The date range <a class="header-anchor" href="#the-date-range" aria-label="Permalink to &quot;The date range&quot;">​</a></h2><p>A date-range control at the top governs every figure below it. Pick one of the presets — <strong>Today</strong>, <strong>This Month</strong>, <strong>Last Month</strong>, <strong>Last 7 Days</strong>, <strong>Last 30 Days</strong>, <strong>Last 6 Months</strong>, <strong>Last Year</strong> — or set your own <strong>Start Date</strong> and <strong>End Date</strong>.</p><p>Changing the range re-reads the whole page, so the trends and totals always describe the same window.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Three cards summarise the health of the store:</p><ul><li><strong>Account Health</strong> — your current verdict: <strong>Healthy</strong>, <strong>At Risk</strong>, <strong>Unhealthy</strong>, or <strong>Not Calculated</strong> if there isn&#39;t enough data yet. See <a href="/sellers/seller-account-health">Seller Account Health</a>.</li><li><strong>Buyer Messages</strong> — how many conversations are waiting, with an <strong>Unread</strong> count. See <a href="/customers/communications">Communications</a>.</li><li><strong>Customer Feedback</strong> — your average rating and the number of reviews behind it. See <a href="/moderation/rating-management">Rating Management</a>.</li></ul><p>Below them, <strong>Trends</strong> charts <strong>Sales</strong> and <strong>Orders</strong> across the selected range.</p><h3 id="things-to-do" tabindex="-1">Things to do <a class="header-anchor" href="#things-to-do" aria-label="Permalink to &quot;Things to do&quot;">​</a></h3><p>A short worklist of everything currently waiting on you:</p><ul><li><strong>Orders awaiting fulfilment</strong></li><li><strong>Products awaiting approval</strong></li><li><strong>Products low on stock</strong></li><li><strong>Unread buyer messages</strong></li></ul><p>When there is nothing outstanding it reads <strong>You are all caught up!</strong> — so an empty list is the goal, not a sign the block is broken.</p><h2 id="overall-details" tabindex="-1">Overall Details <a class="header-anchor" href="#overall-details" aria-label="Permalink to &quot;Overall Details&quot;">​</a></h2><p>Six figures for the selected range:</p><p><strong>Total Sales</strong>, <strong>Total Payout</strong>, <strong>Remaining Payout</strong>, <strong>Total Orders</strong>, <strong>Total Customers</strong>, and <strong>Average Order Sell</strong>.</p><p><strong>Total Payout</strong> is what has already been settled with you; <strong>Remaining Payout</strong> is what you&#39;re still owed. Both come from the same ledger the admin pays you from — see <a href="/payments/payment-management">Payment Management</a>.</p><h2 id="stock-threshold" tabindex="-1">Stock Threshold <a class="header-anchor" href="#stock-threshold" aria-label="Permalink to &quot;Stock Threshold&quot;">​</a></h2><p>The products running low on stock, each with its remaining quantity, and a <strong>View All</strong> link into <a href="/inventory/manage-inventory">Manage Inventory</a>. What counts as &quot;low&quot; is the <strong>Low Stock Threshold</strong> the admin sets under <strong>Configure → Marketplace → Products → Inventory</strong>.</p><p>When nothing is low it shows <strong>Empty Threshold</strong> — there is no product available — which means every listing is comfortably in stock.</p><h2 id="top-categories" tabindex="-1">Top Categories <a class="header-anchor" href="#top-categories" aria-label="Permalink to &quot;Top Categories&quot;">​</a></h2><p>Which of your categories sold best over the selected range. If nothing sold in that window it reads <strong>No Data Available</strong>, with a note that no category was found for the selected interval — widen the range to see more.</p><div class="info custom-block"><p class="custom-block-title">Team members see the shop&#39;s figures</p><p>When a staff user signs in, the greeting and profile prompt are theirs, but every shop-level figure — health, orders, products, reviews — belongs to the shop as a whole. A team member sees the store&#39;s numbers, not an empty dashboard of their own. See <a href="/sellers/seller-user-role-management">Seller Users &amp; Roles</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Work the <strong>Things to do</strong> list first and the rest of the dashboard tends to look after itself — unshipped orders and low stock are the two things that turn into cancellations, and cancellations are the fastest way to damage <a href="/sellers/seller-account-health">account health</a>.</p></div>',25))])}const y=r(g,[["render",d]]);export{b as __pageData,y as default};
